{
  "steps": [
    {
      "id": 1,
      "claim": "Soil texture is defined as the relative proportions of sand, silt, and clay mineral particles in the soil.",
      "evidence": "Standard soil science definition of texture (e.g., USDA soil texture triangle).",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Decomposition of plants and animals produces organic matter (humus) that becomes part of the soil.",
      "evidence": "Biological decomposition processes convert organic residues into humus, a well‑documented component of topsoil.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Organic matter does not change the mineral particle‑size distribution, so it does not alter texture in the strict, technical sense.",
      "evidence": "Texture is based solely on sand, silt, and clay fractions; humus consists of particles smaller than clay and is not counted in the texture triangle.",
      "weight": 0.25,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "In agricultural practice the term “soil texture” is often used loosely to include the effect of organic matter on soil structure, making the soil feel finer and more friable.",
      "evidence": "Textbooks and extension literature describe humus as improving soil “texture” by increasing aggregation and water‑holding capacity.",
      "weight": 0.20,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "Runoff of water, erosion of sand dunes, and compaction of rock layers remove or compact mineral particles, which degrades texture rather than improves it.",
      "evidence": "Runoff transports silt and clay away; dune erosion removes sand; compaction reduces pore space and aggregates, all leading to poorer texture.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 6,
      "claim": "Because option D (decomposition of plants and animals) is the only process that can improve the functional texture of soil, it is the correct answer.",
      "evidence": "Combining steps 4 (functional improvement) and 5 (other options degrade texture) leads to selection of D.",
      "weight": 0.05,
      "depends_on": [4, 5]
    }
  ],
  "answer": "D",
  "confidence": 0.90,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "Runoff removes fine particles, degrading texture."
    },
    {
      "answer": "B",
      "reason_rejected": "Erosion of sand dunes removes sand and does not add fine material or organic matter."
    },
    {
      "answer": "C",
      "reason_rejected": "Compaction reduces pore space and worsens soil structure, not improving texture."
    }
  ]
}
